    return (None, 0.0)

# Initialize extent with the first box.
# We construct a NEW box to avoid modifying the object in the input list
# when we call merge() later.
first = boxes[0]
extent = pyScript.emyBoxF(first.left(), first.bottom(), first.right(), first.top())

# Merge all subsequent boxes into 'extent'
for i in range(1, len(boxes)):
    extent.merge(boxes[i])

# Calculate area using accessor methods
area = extent.getWidth() * extent.getHeight()

return (extent, area)
